class CircuitBreaker:
    def __init__(self, threshold=5, window=60, timeout=30, probes=3):
        self.state, self.failures, self.passed = "closed", list(), 0
        self.threshold, self.window, self.timeout, self.probes = threshold, window, timeout, probes
    def call(self, fn, now):
        if self.state == "open":
            if now - self.opened_at < self.timeout:
                raise RuntimeError("circuit open")
            self.state, self.passed = "half-open", 0
        try:
            result = fn()
        except Exception:
            self.on_failure(now)
            raise
        self.on_success()
        return result
    def on_failure(self, now):
        self.failures = [t for t in self.failures if now - t < self.window] + [now]
        if self.state == "half-open" or len(self.failures) >= self.threshold:
            self.state, self.opened_at = "open", now
    def on_success(self):
        if self.state == "half-open":
            self.passed += 1
            if self.passed >= self.probes:
                self.state, self.failures = "closed", list()
